package com.attendance.controller;

import com.attendance.model.*; import com.attendance.repository.*; import com.attendance.security.*;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.dao.DataIntegrityViolationException;
import java.util.*; import java.time.LocalDate; import java.time.Instant;
import org.springframework.transaction.annotation.Transactional;
import jakarta.servlet.http.HttpServletRequest;

@RestController @RequestMapping("/api")
@CrossOrigin(originPatterns={"http://localhost:[*]","http://127.0.0.1:[*]"})
public class ApiController {
 private final UserRepository users; private final StudentRepository students; private final FacultyRepository faculty; private final SubjectRepository subjects; private final AttendanceRepository attendance; private final AttendanceSessionRepository sessions; private final AttendanceAuditRepository audits; private final ClassScheduleRepository schedules; private final AuthTokenStore tokens;
 public ApiController(UserRepository u,StudentRepository s,FacultyRepository f,SubjectRepository sub,AttendanceRepository a,AttendanceSessionRepository sessions,AttendanceAuditRepository audits,ClassScheduleRepository schedules,AuthTokenStore tokens){users=u;students=s;faculty=f;subjects=sub;attendance=a;this.sessions=sessions;this.audits=audits;this.schedules=schedules;this.tokens=tokens;}
 private AuthTokenStore.Principal principal(HttpServletRequest request){return (AuthTokenStore.Principal)request.getAttribute(ApiAuthenticationFilter.PRINCIPAL_ATTRIBUTE);}
 private void requireRole(HttpServletRequest request,String... allowed){AuthTokenStore.Principal p=principal(request);if(p==null||Arrays.stream(allowed).noneMatch(p.role()::equals))throw new SecurityException("You do not have permission to perform this action.");}
 private boolean belongsToFaculty(Subject subject,AuthTokenStore.Principal p){return subject.faculty!=null&&subject.faculty.user!=null&&p.username().equals(subject.faculty.user.username);}
 private void requireFacultyScope(Subject subject,HttpServletRequest request){AuthTokenStore.Principal p=principal(request);if("FACULTY".equals(p.role())&&!belongsToFaculty(subject,p))throw new SecurityException("You can only manage attendance for your assigned subjects.");}
 private boolean matchesClass(Student student,Subject subject){return (subject.department==null||Objects.equals(subject.department,student.department))&&(subject.year==null||Objects.equals(subject.year,student.year))&&(subject.section==null||Objects.equals(subject.section,student.section));} private void ensureClassMember(Student student,Subject subject){if(!matchesClass(student,subject))throw new IllegalArgumentException("Student does not belong to this subject's department, year, and section.");}
 private Set<Long> assignedSubjectIds(AuthTokenStore.Principal p){Long id=faculty.findAll().stream().filter(f->f.user!=null&&p.username().equals(f.user.username)).map(f->f.id).findFirst().orElse(-1L);return subjects.findByFaculty_Id(id).stream().map(s->s.id).collect(java.util.stream.Collectors.toSet());}
 private void ensureCanView(Attendance row,HttpServletRequest request){AuthTokenStore.Principal p=principal(request);if("STUDENT".equals(p.role())&&!Objects.equals(row.student.id,ownStudent(request).id))throw new SecurityException("You can only view your own attendance.");if("FACULTY".equals(p.role()))requireFacultyScope(row.subject,request);}
 private Student ownStudent(HttpServletRequest request){AuthTokenStore.Principal p=principal(request);return students.findByUser_Username(p.username()).orElseThrow(()->new SecurityException("Your login is not linked to a student profile."));}
 private void audit(Attendance row,String action,String previous,String next,String actor){AttendanceAudit entry=new AttendanceAudit();entry.attendanceId=row.id;entry.action=action;entry.studentCode=row.student.studentId;entry.studentName=row.student.name;entry.subjectCode=row.subject.subjectCode;entry.subjectName=row.subject.subjectName;entry.attendanceDate=row.attendanceDate;entry.previousStatus=previous;entry.newStatus=next;entry.changedBy=actor;entry.changedAt=Instant.now();audits.save(entry);}
 private RuntimeException missing(String what){return new NoSuchElementException(what+" not found");}
 @ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> notFound(Exception e){return ResponseEntity.status(404).body(Map.of("message",e.getMessage()));}
 @ExceptionHandler({IllegalArgumentException.class,DataIntegrityViolationException.class}) ResponseEntity<?> bad(Exception e){String m=e instanceof DataIntegrityViolationException?"Duplicate value or linked record prevents this operation":e.getMessage();return ResponseEntity.badRequest().body(Map.of("message",m==null?"Invalid request":m));}
 @ExceptionHandler(SecurityException.class) ResponseEntity<?> forbidden(Exception e){return ResponseEntity.status(HttpStatus.FORBIDDEN).body(Map.of("message",e.getMessage()));}
 @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Map<String,String> body){User u=users.findByUsername(body.get("username")==null?"":body.get("username").trim()).orElseThrow(()->new IllegalArgumentException("Invalid username or password"));if(!Objects.equals(u.password,body.get("password")))throw new IllegalArgumentException("Invalid username or password");return Map.of("success",true,"message","Login successful","role",u.role,"username",u.username,"token",tokens.issue(u));}
 @PostMapping("/auth/logout") public Map<String,String> logout(HttpServletRequest request){String header=request.getHeader("Authorization");if(header!=null&&header.startsWith("Bearer "))tokens.revoke(header.substring(7).trim());return Map.of("message","Logged out");}
 @GetMapping("/students") public List<Student> students(HttpServletRequest request){AuthTokenStore.Principal p=principal(request);if("ADMIN".equals(p.role()))return students.findAll();if("STUDENT".equals(p.role()))return List.of(ownStudent(request));List<Subject> assigned=subjects.findByFaculty_Id(faculty.findAll().stream().filter(f->f.user!=null&&p.username().equals(f.user.username)).map(f->f.id).findFirst().orElse(-1L));return students.findAll().stream().filter(st->assigned.stream().anyMatch(sub->matchesClass(st,sub))).toList();} @GetMapping("/students/{id}") public Student student(@PathVariable Long id,HttpServletRequest request){Student s=student(id);AuthTokenStore.Principal p=principal(request);if("STUDENT".equals(p.role())&&!Objects.equals(s.user==null?null:s.user.username,p.username()))throw new SecurityException("You can only view your own student record.");if("FACULTY".equals(p.role())){boolean assigned=subjects.findByFaculty_Id(faculty.findAll().stream().filter(f->f.user!=null&&p.username().equals(f.user.username)).map(f->f.id).findFirst().orElse(-1L)).stream().anyMatch(sub->matchesClass(s,sub));if(!assigned)throw new SecurityException("You can only view students in your assigned classes.");}return s;}
 private Student student(Long id){return students.findById(id).orElseThrow(()->missing("Student"));}
 @Transactional @PostMapping("/students") public Student addStudent(@RequestBody Map<String,Object> b,HttpServletRequest request){requireRole(request,"ADMIN");Student s=new Student();fillStudent(s,b);Object username=b.get("username");if(username!=null&&!username.toString().isBlank()){String name=username.toString();if(users.findByUsername(name).isPresent())throw new IllegalArgumentException("Username already exists");s.user=users.save(new User(name,b.getOrDefault("password","student123").toString(),"STUDENT"));}return students.save(s);}
 @PutMapping("/students/{id}") public Student updateStudent(@PathVariable Long id,@RequestBody Map<String,Object> b,HttpServletRequest request){requireRole(request,"ADMIN");Student s=student(id);fillStudent(s,b);return students.save(s);}
 private void fillStudent(Student s,Map<String,Object>b){s.studentId=(String)b.get("studentId");s.name=(String)b.get("name");s.email=(String)b.get("email");s.phone=(String)b.get("phone");s.department=(String)b.get("department");s.year=b.get("year")==null||b.get("year").toString().isBlank()?null:Integer.valueOf(b.get("year").toString());s.section=(String)b.get("section");if(s.studentId==null||s.studentId.isBlank()||s.name==null||s.name.isBlank()||s.email==null||!s.email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new IllegalArgumentException("Student ID, name and valid email are required");if(s.phone!=null&&!s.phone.isBlank()&&!s.phone.matches("[0-9+() .-]{7,20}"))throw new IllegalArgumentException("Phone number is invalid");}
 @Transactional @DeleteMapping("/students/{id}") public Map<String,String> deleteStudent(@PathVariable Long id,HttpServletRequest request){requireRole(request,"ADMIN");Student selected=student(id);attendance.deleteByStudent_Id(id);students.delete(selected);if(selected.user!=null)users.delete(selected.user);return Map.of("message","Student and linked attendance records deleted");}
 @GetMapping("/faculty") public List<Faculty> faculties(HttpServletRequest request){requireRole(request,"ADMIN");return faculty.findAll();} @GetMapping("/faculty/{id}") public Faculty fac(@PathVariable Long id,HttpServletRequest request){requireRole(request,"ADMIN");return facultyById(id);} private Faculty facultyById(Long id){return faculty.findById(id).orElseThrow(()->missing("Faculty"));}
 @Transactional @PostMapping("/faculty") public Faculty addFaculty(@RequestBody Map<String,Object> b,HttpServletRequest request){requireRole(request,"ADMIN");Faculty f=new Faculty();fillFaculty(f,b);Object username=b.get("username");if(username!=null&&!username.toString().isBlank()){String name=username.toString();if(users.findByUsername(name).isPresent())throw new IllegalArgumentException("Username already exists");f.user=users.save(new User(name,b.getOrDefault("password","faculty123").toString(),"FACULTY"));}return faculty.save(f);}
 @PutMapping("/faculty/{id}") public Faculty updateFaculty(@PathVariable Long id,@RequestBody Map<String,Object> b,HttpServletRequest request){requireRole(request,"ADMIN");Faculty f=facultyById(id);fillFaculty(f,b);return faculty.save(f);}
 private void fillFaculty(Faculty f,Map<String,Object>b){f.facultyId=(String)b.get("facultyId");f.name=(String)b.get("name");f.email=(String)b.get("email");f.phone=(String)b.get("phone");f.department=(String)b.get("department");if(f.facultyId==null||f.facultyId.isBlank()||f.name==null||f.name.isBlank()||f.email==null||!f.email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new IllegalArgumentException("Faculty ID, name and valid email are required");if(f.phone!=null&&!f.phone.isBlank()&&!f.phone.matches("[0-9+() .-]{7,20}"))throw new IllegalArgumentException("Phone number is invalid");}
 @Transactional @DeleteMapping("/faculty/{id}") public Map<String,String> deleteFaculty(@PathVariable Long id,HttpServletRequest request){requireRole(request,"ADMIN");Faculty selected=facultyById(id);sessions.deleteByFaculty_Id(id);for(Subject assigned:subjects.findByFaculty_Id(id))assigned.faculty=null;faculty.delete(selected);if(selected.user!=null)users.delete(selected.user);return Map.of("message","Faculty deleted; assigned subjects were unassigned");}
 @GetMapping("/faculty/overview") public Map<String,Object> facultyOverview(HttpServletRequest request){requireRole(request,"FACULTY");AuthTokenStore.Principal p=principal(request);Faculty owner=faculty.findAll().stream().filter(f->f.user!=null&&p.username().equals(f.user.username)).findFirst().orElseThrow(()->new SecurityException("Faculty profile not found."));List<Subject> assigned=subjects.findByFaculty_Id(owner.id);List<Map<String,Object>> summaries=new ArrayList<>();Set<Long> atRiskStudents=new HashSet<>();Set<String> conductedClasses=new HashSet<>();for(Subject selected:assigned){List<Attendance> rows=attendance.findBySubject_Id(selected.id);rows.forEach(a->conductedClasses.add(selected.id+"|"+a.attendanceDate));Map<Long,List<Attendance>> byStudent=new HashMap<>();for(Attendance row:rows)byStudent.computeIfAbsent(row.student.id,k->new ArrayList<>()).add(row);long low=0,absentCount=0;for(Map.Entry<Long,List<Attendance>> e:byStudent.entrySet()){List<Attendance> studentRows=e.getValue();long presentCount=studentRows.stream().filter(a->"PRESENT".equals(a.status)).count();if(!studentRows.isEmpty()&&presentCount*100.0/studentRows.size()<80){low++;atRiskStudents.add(e.getKey());}absentCount+=studentRows.stream().filter(a->"ABSENT".equals(a.status)).count();}long presentCount=rows.stream().filter(a->"PRESENT".equals(a.status)).count();Map<String,Object> summary=new LinkedHashMap<>();summary.put("subjectId",selected.id);summary.put("subjectCode",selected.subjectCode);summary.put("subjectName",selected.subjectName);summary.put("department",Objects.toString(selected.department,""));summary.put("year",Objects.toString(selected.year,""));summary.put("section",Objects.toString(selected.section,""));summary.put("classesConducted",rows.stream().map(a->a.attendanceDate).distinct().count());summary.put("records",rows.size());summary.put("present",presentCount);summary.put("absent",absentCount);summary.put("percentage",rows.isEmpty()?0.0:Math.round(presentCount*1000.0/rows.size())/10.0);summary.put("studentsBelowWarning",low);summaries.add(summary);}long pending=sessions.findByFaculty_IdAndActiveTrue(owner.id).stream().filter(s->s.expiresAt.isAfter(Instant.now())).count();return Map.of("facultyId",owner.facultyId,"classesConducted",conductedClasses.size(),"pendingSessions",pending,"studentsAtRisk",atRiskStudents.size(),"subjects",summaries);}
 @GetMapping("/schedules") public List<Map<String,Object>> scheduleList(HttpServletRequest request){AuthTokenStore.Principal p=principal(request);return schedules.findAllByOrderByDayOfWeekAscStartTimeAsc().stream().filter(row->row.active&&("ADMIN".equals(p.role())||("FACULTY".equals(p.role())&&belongsToFaculty(row.subject,p))||("STUDENT".equals(p.role())&&matchesClass(ownStudent(request),row.subject)))).map(this::scheduleDto).toList();}
 @PostMapping("/schedules") public Map<String,Object> addSchedule(@RequestBody Map<String,Object> body,HttpServletRequest request){requireRole(request,"ADMIN");ClassSchedule row=new ClassSchedule();fillSchedule(row,body);return scheduleDto(schedules.save(row));}
 @PutMapping("/schedules/{id}") public Map<String,Object> updateSchedule(@PathVariable Long id,@RequestBody Map<String,Object> body,HttpServletRequest request){requireRole(request,"ADMIN");ClassSchedule row=schedules.findById(id).orElseThrow(()->missing("Class schedule"));fillSchedule(row,body);return scheduleDto(schedules.save(row));}
 @DeleteMapping("/schedules/{id}") public Map<String,String> deleteSchedule(@PathVariable Long id,HttpServletRequest request){requireRole(request,"ADMIN");ClassSchedule row=schedules.findById(id).orElseThrow(()->missing("Class schedule"));schedules.delete(row);return Map.of("message","Class schedule removed.");}
 private void fillSchedule(ClassSchedule row,Map<String,Object> body){try{if(body.get("subjectId")==null||body.get("dayOfWeek")==null||body.get("startTime")==null||body.get("endTime")==null)throw new IllegalArgumentException("Subject, day, start time, and end time are required.");row.subject=subject(Long.valueOf(body.get("subjectId").toString()));row.dayOfWeek=body.get("dayOfWeek").toString().toUpperCase(Locale.ROOT);if(!Set.of("MONDAY","TUESDAY","WEDNESDAY","THURSDAY","FRIDAY","SATURDAY","SUNDAY").contains(row.dayOfWeek))throw new IllegalArgumentException("Choose a valid weekday.");row.startTime=java.time.LocalTime.parse(body.get("startTime").toString());row.endTime=java.time.LocalTime.parse(body.get("endTime").toString());if(!row.startTime.isBefore(row.endTime))throw new IllegalArgumentException("End time must be later than start time.");row.room=body.get("room")==null?"":body.get("room").toString().trim();row.active=true;}catch(java.time.DateTimeException|NumberFormatException e){throw new IllegalArgumentException("Schedule contains an invalid subject or time.");}}
 private Map<String,Object> scheduleDto(ClassSchedule row){Map<String,Object> out=new LinkedHashMap<>();out.put("id",row.id);out.put("subjectId",row.subject.id);out.put("subjectCode",row.subject.subjectCode);out.put("subjectName",row.subject.subjectName);out.put("department",Objects.toString(row.subject.department,""));out.put("year",Objects.toString(row.subject.year,""));out.put("section",Objects.toString(row.subject.section,""));out.put("facultyName",row.subject.faculty==null?"Unassigned":row.subject.faculty.name);out.put("dayOfWeek",row.dayOfWeek);out.put("startTime",row.startTime);out.put("endTime",row.endTime);out.put("room",Objects.toString(row.room,""));return out;}
 @GetMapping("/subjects") public List<Subject> subjectList(HttpServletRequest request){AuthTokenStore.Principal p=principal(request);if("ADMIN".equals(p.role()))return subjects.findAll();if("FACULTY".equals(p.role())){Long fid=faculty.findAll().stream().filter(f->f.user!=null&&p.username().equals(f.user.username)).map(f->f.id).findFirst().orElse(-1L);return subjects.findByFaculty_Id(fid);}Student own=ownStudent(request);return subjects.findAll().stream().filter(s->(s.department==null||Objects.equals(s.department,own.department))&&(s.year==null||Objects.equals(s.year,own.year))&&(s.section==null||Objects.equals(s.section,own.section))).toList();} @GetMapping("/subjects/{id}") public Subject subject(@PathVariable Long id){return subjects.findById(id).orElseThrow(()->missing("Subject"));}
 @PostMapping("/subjects") public Subject addSubject(@RequestBody Map<String,Object> b,HttpServletRequest request){requireRole(request,"ADMIN");Subject s=new Subject();fillSubject(s,b);return subjects.save(s);}
 @PutMapping("/subjects/{id}") public Subject updateSubject(@PathVariable Long id,@RequestBody Map<String,Object>b,HttpServletRequest request){requireRole(request,"ADMIN");Subject s=subject(id);fillSubject(s,b);return subjects.save(s);}
 private void fillSubject(Subject s,Map<String,Object>b){s.subjectCode=b.get("subjectCode")==null?null:b.get("subjectCode").toString().trim();s.subjectName=b.get("subjectName")==null?null:b.get("subjectName").toString().trim();s.department=(String)b.get("department");Object year=b.get("year");s.year=year==null||year.toString().isBlank()?null:Integer.valueOf(year.toString());s.section=(String)b.get("section");Object fid=b.get("facultyId");s.faculty=fid==null||fid.toString().isBlank()?null:facultyById(Long.valueOf(fid.toString()));if(s.subjectCode==null||s.subjectCode.isBlank()||s.subjectName==null||s.subjectName.isBlank())throw new IllegalArgumentException("Subject code and name are required");if(s.year!=null&&s.year<1)throw new IllegalArgumentException("Year must be a positive number");}
 @Transactional @DeleteMapping("/subjects/{id}") public Map<String,String> deleteSubject(@PathVariable Long id,HttpServletRequest request){requireRole(request,"ADMIN");Subject selected=subject(id);sessions.deleteBySubject_Id(id);attendance.deleteBySubject_Id(id);subjects.delete(selected);return Map.of("message","Subject and linked attendance records deleted");}
 @GetMapping("/attendance") public List<Map<String,Object>> attendanceList(HttpServletRequest request){AuthTokenStore.Principal p=principal(request);List<Attendance> rows=attendance.findAll();if("STUDENT".equals(p.role())){Long sid=ownStudent(request).id;rows=rows.stream().filter(a->Objects.equals(a.student.id,sid)).toList();}else if("FACULTY".equals(p.role())){Set<Long> subjectIds=assignedSubjectIds(p);rows=rows.stream().filter(a->subjectIds.contains(a.subject.id)).toList();}return rows.stream().map(this::attendanceDto).toList();}
 @GetMapping("/attendance/{id}") public Map<String,Object> attendanceOne(@PathVariable Long id,HttpServletRequest request){Attendance row=attendance.findById(id).orElseThrow(()->missing("Attendance"));ensureCanView(row,request);return attendanceDto(row);}
 @GetMapping("/attendance/student/{studentId}") public List<Map<String,Object>> byStudent(@PathVariable String studentId,HttpServletRequest request){Student s=students.findByStudentId(studentId).orElseThrow(()->missing("Student"));AuthTokenStore.Principal p=principal(request);if("STUDENT".equals(p.role())&&!Objects.equals(s.id,ownStudent(request).id))throw new SecurityException("You can only view your own attendance.");List<Attendance> rows=attendance.findByStudent_Id(s.id);if("FACULTY".equals(p.role()))rows=rows.stream().filter(a->belongsToFaculty(a.subject,p)).toList();return rows.stream().map(this::attendanceDto).toList();}
 @GetMapping("/attendance/subject/{subjectId}") public List<Map<String,Object>> bySubject(@PathVariable Long subjectId,HttpServletRequest request){Subject selected=subject(subjectId);requireFacultyScope(selected,request);List<Attendance> rows=attendance.findBySubject_Id(subjectId);if("STUDENT".equals(principal(request).role())){Long sid=ownStudent(request).id;rows=rows.stream().filter(a->Objects.equals(a.student.id,sid)).toList();}return rows.stream().map(this::attendanceDto).toList();}
 @GetMapping("/attendance/date/{date}") public List<Map<String,Object>> byDate(@PathVariable LocalDate date,HttpServletRequest request){List<Attendance> rows=attendance.findByAttendanceDate(date);AuthTokenStore.Principal p=principal(request);if("STUDENT".equals(p.role())){Long sid=ownStudent(request).id;rows=rows.stream().filter(a->Objects.equals(a.student.id,sid)).toList();}else if("FACULTY".equals(p.role())){Set<Long> ids=assignedSubjectIds(p);rows=rows.stream().filter(a->ids.contains(a.subject.id)).toList();}return rows.stream().map(this::attendanceDto).toList();}
 @GetMapping("/attendance/percentage/{studentId}") public Map<String,Object> percentage(@PathVariable String studentId,HttpServletRequest request){Student student=students.findByStudentId(studentId).orElseThrow(()->missing("Student"));AuthTokenStore.Principal p=principal(request);if("STUDENT".equals(p.role())&&!Objects.equals(student.id,ownStudent(request).id))throw new SecurityException("You can only view your own attendance.");List<Attendance> rows=attendance.findByStudent_Id(student.id);if("FACULTY".equals(p.role()))rows=rows.stream().filter(a->belongsToFaculty(a.subject,p)).toList();long present=rows.stream().filter(a->"PRESENT".equals(a.status)).count();return Map.of("studentId",studentId,"total",rows.size(),"present",present,"absent",rows.size()-present,"percentage",rows.isEmpty()?0.0:Math.round(present*1000.0/rows.size())/10.0);}
 @GetMapping("/attendance/student/{studentCode}/insights") public Map<String,Object> attendanceInsights(@PathVariable String studentCode,HttpServletRequest request){Student student=students.findByStudentId(studentCode).orElseThrow(()->missing("Student"));AuthTokenStore.Principal p=principal(request);if("STUDENT".equals(p.role())&&!Objects.equals(student.id,ownStudent(request).id))throw new SecurityException("You can only view your own attendance.");List<Attendance> all=attendance.findByStudent_Id(student.id);if("FACULTY".equals(p.role()))all=all.stream().filter(a->belongsToFaculty(a.subject,p)).toList();Map<Long,List<Attendance>> grouped=new LinkedHashMap<>();for(Attendance row:all)grouped.computeIfAbsent(row.subject.id,k->new ArrayList<>()).add(row);List<Map<String,Object>> bySubject=new ArrayList<>();List<Map<String,Object>> alerts=new ArrayList<>();for(Map.Entry<Long,List<Attendance>> entry:grouped.entrySet()){Subject selected=entry.getValue().get(0).subject;Map<String,Object> summary=attendanceSummary(selected.subjectName,entry.getValue());summary.put("subjectCode",selected.subjectCode);bySubject.add(summary);String level=(String)summary.get("riskLevel");if(!"LOW".equals(level))alerts.add(Map.of("subjectName",selected.subjectName,"riskLevel",level,"percentage",summary.get("percentage"),"message",level.equals("CRITICAL")?"Attendance is below 75%.":"Attendance is below 80%."));if(((Number)summary.get("consecutiveAbsences")).intValue()>=2)alerts.add(Map.of("subjectName",selected.subjectName,"riskLevel","WARNING","percentage",summary.get("percentage"),"message","You have consecutive absences in this subject."));}Map<String,Object> overall=attendanceSummary("Overall",all);return Map.of("studentCode",studentCode,"overall",overall,"subjects",bySubject,"alerts",alerts);}
 private Map<String,Object> attendanceSummary(String name,List<Attendance> rows){long attended=rows.stream().filter(a->"PRESENT".equals(a.status)).count();int total=rows.size();double percentage=total==0?0.0:Math.round(attended*1000.0/total)/10.0;List<Attendance> sorted=rows.stream().sorted(Comparator.comparing((Attendance a)->a.attendanceDate).reversed()).toList();List<Attendance> recent=sorted.stream().limit(5).toList();long recentPresent=recent.stream().filter(a->"PRESENT".equals(a.status)).count();double recentPercentage=recent.isEmpty()?percentage:Math.round(recentPresent*1000.0/recent.size())/10.0;boolean atTarget=attended*100>=total*75L;int required=atTarget?0:(int)Math.ceil(Math.max(0,0.75*total-attended)/0.25);int safeMisses=attended*100>=total*75L?(int)Math.max(0,Math.floor(attended/0.75-total)):0;long consecutive=0;for(Attendance row:sorted){if(!"ABSENT".equals(row.status))break;consecutive++;}String risk=percentage<75?"CRITICAL":percentage<80?"WARNING":"LOW";String band=percentage<75?"HIGH":percentage<85?"MODERATE":"LOW";int score=(int)Math.max(0,Math.min(100,Math.round(Math.max(0,80-percentage)*1.8+consecutive*8+Math.max(0,percentage-recentPercentage)*0.55)));List<Map<String,Object>> projections=new ArrayList<>();for(int missed:new int[]{1,3,5,10}){double projected=total+missed==0?0:Math.round(attended*1000.0/(total+missed))/10.0;projections.add(Map.of("missedUpcomingClasses",missed,"projectedPercentage",projected,"riskLevel",projected<75?"CRITICAL":projected<80?"WARNING":"LOW"));}Map<String,Object> summary=new LinkedHashMap<>();summary.put("subjectName",name);summary.put("attended",attended);summary.put("total",total);summary.put("percentage",percentage);summary.put("riskLevel",risk);summary.put("riskBand",band);summary.put("riskScore",score);summary.put("recentPercentage",recentPercentage);summary.put("recentClasses",recent.size());summary.put("requiredConsecutiveClasses",required);summary.put("safeClassesToMiss",safeMisses);summary.put("consecutiveAbsences",consecutive);summary.put("projections",projections);return summary;}
 @PostMapping("/attendance/sessions") public ResponseEntity<?> createAttendanceSession(@RequestBody Map<String,Object> body,HttpServletRequest request){requireRole(request,"FACULTY");AuthTokenStore.Principal p=principal(request);if(body.get("subjectId")==null)return ResponseEntity.badRequest().body(Map.of("message","Subject is required"));Subject selected=subject(Long.valueOf(body.get("subjectId").toString()));requireFacultyScope(selected,request);Instant now=Instant.now();AttendanceSession session=new AttendanceSession();session.token=UUID.randomUUID().toString();session.subject=selected;session.faculty=faculty.findAll().stream().filter(f->f.user!=null&&p.username().equals(f.user.username)).findFirst().orElseThrow(()->new SecurityException("Faculty profile not found."));session.createdAt=now;session.expiresAt=now.plusSeconds(120);Object requestedDate=body.get("attendanceDate");session.sessionDate=requestedDate==null||requestedDate.toString().isBlank()?LocalDate.now():LocalDate.parse(requestedDate.toString());if(session.sessionDate.isAfter(LocalDate.now()))throw new IllegalArgumentException("Attendance date cannot be in the future");sessions.save(session);return ResponseEntity.ok(Map.of("token",session.token,"subjectName",selected.subjectName,"expiresAt",session.expiresAt,"expiresInSeconds",120,"sessionDate",session.sessionDate));}
 @GetMapping("/attendance/sessions/{token}") public ResponseEntity<?> getAttendanceSession(@PathVariable String token,HttpServletRequest request){AttendanceSession session=sessions.findByToken(token).orElse(null);if(session==null||!session.active||!session.expiresAt.isAfter(Instant.now()))return ResponseEntity.status(HttpStatus.GONE).body(Map.of("message","Attendance QR code has expired"));return ResponseEntity.ok(Map.of("subjectName",session.subject.subjectName,"expiresAt",session.expiresAt,"sessionDate",session.sessionDate==null?session.createdAt.atZone(java.time.ZoneId.systemDefault()).toLocalDate():session.sessionDate));}
 @Transactional @PostMapping("/attendance/sessions/{token}/checkins") public ResponseEntity<?> submitQrAttendance(@PathVariable String token,@RequestBody Map<String,Object> body,HttpServletRequest request){requireRole(request,"STUDENT");AuthTokenStore.Principal p=principal(request);AttendanceSession session=sessions.findByToken(token).orElse(null);if(session==null||!session.active||!session.expiresAt.isAfter(Instant.now()))return ResponseEntity.status(HttpStatus.GONE).body(Map.of("message","Attendance QR code has expired"));Student student=students.findByUser_Username(p.username()).orElse(null);if(student==null)return ResponseEntity.status(HttpStatus.FORBIDDEN).body(Map.of("message","No student profile is linked to this account"));if(attendance.findBySessionIdAndStudent_Id(session.id,student.id).isPresent())return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("message","Attendance already recorded for this student and session."));Subject course=session.subject;if((course.department!=null&&!Objects.equals(course.department,student.department))||(course.year!=null&&!Objects.equals(course.year,student.year))||(course.section!=null&&!Objects.equals(course.section,student.section)))return ResponseEntity.status(HttpStatus.FORBIDDEN).body(Map.of("message","You are not enrolled in this subject class."));LocalDate classDate=session.sessionDate==null?session.createdAt.atZone(java.time.ZoneId.systemDefault()).toLocalDate():session.sessionDate;if(attendance.findByStudent_IdAndSubject_IdAndAttendanceDate(student.id,course.id,classDate).isPresent())return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("message","Attendance has already been recorded for this subject and date."));Attendance record=new Attendance();record.student=student;record.subject=course;record.attendanceDate=classDate;record.sessionId=session.id;record.status="PRESENT";record.markedBy=p.username();Attendance saved=attendance.save(record);audit(saved,"QR_CHECK_IN",null,saved.status,p.username());return ResponseEntity.ok(attendanceDto(saved));}
 @Transactional @PostMapping("/attendance") public ResponseEntity<?> addAttendance(@RequestBody Map<String,Object>b,HttpServletRequest request){requireRole(request,"ADMIN","FACULTY");Attendance a=new Attendance();fillAttendance(a,b);requireFacultyScope(a.subject,request);ensureClassMember(a.student,a.subject);if(attendance.findByStudent_IdAndSubject_IdAndAttendanceDate(a.student.id,a.subject.id,a.attendanceDate).isPresent())return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("message","Attendance already recorded for this student and class date."));a.markedBy=("ADMIN".equals(principal(request).role())&&Boolean.TRUE.equals(b.get("demoRecord")))?"DEMO DATA":principal(request).username();Attendance saved=attendance.save(a);audit(saved,"MARKED",null,saved.status,principal(request).username());return ResponseEntity.ok(attendanceDto(saved));}
 @Transactional @PostMapping("/attendance/import") public ResponseEntity<?> importAttendance(@RequestBody List<Map<String,Object>> rows,HttpServletRequest request){requireRole(request,"ADMIN");if(rows==null||rows.isEmpty())throw new IllegalArgumentException("The CSV file has no attendance rows.");if(rows.size()>10000)throw new IllegalArgumentException("Import is limited to 10,000 records at a time.");List<Attendance> pending=new ArrayList<>();Set<String> keys=new HashSet<>();for(int i=0;i<rows.size();i++){try{Attendance row=new Attendance();fillAttendance(row,rows.get(i));ensureClassMember(row.student,row.subject);String key=row.student.id+"|"+row.subject.id+"|"+row.attendanceDate;if(!keys.add(key))throw new IllegalArgumentException("Duplicate student, subject, and date in this file.");if(attendance.findByStudent_IdAndSubject_IdAndAttendanceDate(row.student.id,row.subject.id,row.attendanceDate).isPresent())throw new IllegalArgumentException("Attendance already exists for this student, subject, and date.");row.markedBy=principal(request).username();pending.add(row);}catch(RuntimeException e){throw new IllegalArgumentException("CSV row "+(i+2)+": "+e.getMessage(),e);}}List<Attendance> saved=attendance.saveAll(pending);for(Attendance row:saved)audit(row,"CSV_IMPORTED",null,row.status,principal(request).username());return ResponseEntity.ok(Map.of("imported",saved.size(),"message",saved.size()+" attendance records imported successfully."));}
 @Transactional @DeleteMapping("/attendance/demo") public Map<String,Object> deleteDemoAttendance(HttpServletRequest request){requireRole(request,"ADMIN");List<Attendance> demo=attendance.findByMarkedBy("DEMO DATA");for(Attendance row:demo)audit(row,"DEMO_REMOVED",row.status,null,principal(request).username());attendance.deleteAll(demo);return Map.of("deleted",demo.size(),"message",demo.size()+" demo attendance records removed.");}
 @Transactional @PutMapping("/attendance/{id}") public Map<String,Object> updateAttendance(@PathVariable Long id,@RequestBody Map<String,Object>b,HttpServletRequest request){requireRole(request,"ADMIN","FACULTY");Attendance a=attendance.findById(id).orElseThrow(()->missing("Attendance"));requireFacultyScope(a.subject,request);String previous=a.status;fillAttendance(a,b);requireFacultyScope(a.subject,request);ensureClassMember(a.student,a.subject);a.markedBy=("ADMIN".equals(principal(request).role())&&Boolean.TRUE.equals(b.get("demoRecord")))?"DEMO DATA":principal(request).username();Attendance saved=attendance.save(a);audit(saved,Objects.equals(previous,saved.status)?"EDITED":"CORRECTED",previous,saved.status,principal(request).username());return attendanceDto(saved);}
 private void fillAttendance(Attendance a,Map<String,Object>b){try{if(b.get("studentId")==null||b.get("subjectId")==null||b.get("attendanceDate")==null||b.get("status")==null)throw new IllegalArgumentException("Student, subject, date and status are required");a.student=students.findById(Long.valueOf(b.get("studentId").toString())).orElseThrow(()->missing("Student"));a.subject=subject(Long.valueOf(b.get("subjectId").toString()));a.attendanceDate=LocalDate.parse(b.get("attendanceDate").toString());if(a.attendanceDate.isAfter(LocalDate.now()))throw new IllegalArgumentException("Attendance date cannot be in the future");a.status=b.get("status").toString().toUpperCase(Locale.ROOT);if(!Set.of("PRESENT","ABSENT").contains(a.status))throw new IllegalArgumentException("Status must be PRESENT or ABSENT");a.markedBy=b.get("markedBy")==null?"":b.get("markedBy").toString();}catch(java.time.DateTimeException|NumberFormatException e){throw new IllegalArgumentException("Attendance contains an invalid ID or date");}}
 @Transactional @DeleteMapping("/attendance/{id}") public Map<String,String> deleteAttendance(@PathVariable Long id,HttpServletRequest request){requireRole(request,"ADMIN","FACULTY");Attendance row=attendance.findById(id).orElseThrow(()->missing("Attendance"));requireFacultyScope(row.subject,request);audit(row,"DELETED",row.status,null,principal(request).username());attendance.delete(row);return Map.of("message","Attendance deleted and recorded in audit history.");}
 @GetMapping("/attendance/audit") public List<AttendanceAudit> attendanceAudit(HttpServletRequest request){AuthTokenStore.Principal p=principal(request);if("ADMIN".equals(p.role()))return audits.findAllByOrderByChangedAtDesc();if("STUDENT".equals(p.role()))return audits.findByStudentCodeOrderByChangedAtDesc(ownStudent(request).studentId);Set<String> codes=subjects.findByFaculty_Id(faculty.findAll().stream().filter(f->f.user!=null&&p.username().equals(f.user.username)).map(f->f.id).findFirst().orElse(-1L)).stream().map(s->s.subjectCode).collect(java.util.stream.Collectors.toSet());return audits.findAllByOrderByChangedAtDesc().stream().filter(a->codes.contains(a.subjectCode)).toList();}
 private Map<String,Object> attendanceDto(Attendance a){return Map.of("id",a.id,"studentId",a.student.id,"studentCode",a.student.studentId,"studentName",a.student.name,"subjectId",a.subject.id,"subjectCode",a.subject.subjectCode,"subjectName",a.subject.subjectName,"attendanceDate",a.attendanceDate,"status",a.status,"markedBy",a.markedBy==null?"":a.markedBy);}
}
